<?php
require __DIR__.'/config.php';
header('Content-Type: application/json; charset=utf-8');
$origin=$_SERVER['HTTP_ORIGIN']??'';
if(in_array($origin,['http://localhost:5173','http://127.0.0.1:5173'],true)){header('Access-Control-Allow-Origin: '.$origin);header('Access-Control-Allow-Credentials: true');header('Vary: Origin');}
header('Access-Control-Allow-Headers: Content-Type, X-CSRF-Token');header('Access-Control-Allow-Methods: GET,POST,PATCH,PUT,DELETE,OPTIONS');
if($_SERVER['REQUEST_METHOD']==='OPTIONS')exit;
ini_set('session.use_strict_mode','1');ini_set('session.cookie_httponly','1');ini_set('session.cookie_samesite','Lax');session_start();
function out($data,$code=200){http_response_code($code);echo json_encode($data);exit;}
function fail($msg,$code=400){out(['error'=>$msg],$code);}
function body(){return json_decode(file_get_contents('php://input'),true)??[];}
function user(){if(empty($_SESSION['uid']))fail('Please log in',401);$s=db()->prepare('SELECT id,full_name,username,email,role,status FROM users WHERE id=?');$s->execute([$_SESSION['uid']]);$u=$s->fetch();if(!$u||$u['status']!=='active')fail('Access denied',403);return $u;}
function roles($u,...$r){if(!in_array($u['role'],$r,true))fail('Not authorized',403);}
function query($sql,$params=[]){$s=db()->prepare($sql);$s->execute($params);return $s;}
function logaction($u,$a){query('INSERT INTO activity_logs(user_id,action) VALUES(?,?)',[$u['id'],$a]);}
function accessible($u,$id){$p=query('SELECT * FROM projects WHERE id=?',[$id])->fetch();if(!$p)fail('Project not found',404);if($u['role']==='teacher' && $p['teacher_id']!=$u['id'])fail('Forbidden',403);if($u['role']==='student'&&!query('SELECT 1 FROM project_members WHERE project_id=? AND student_id=?',[$id,$u['id']])->fetch())fail('Forbidden',403);return $p;}
try{
$path=trim(parse_url($_SERVER['REQUEST_URI'],PHP_URL_PATH),'/');$path=preg_replace('~^monitoring/backend/?~','',$path);$method=$_SERVER['REQUEST_METHOD'];
if($path==='api/auth/login'&&$method==='POST'){$b=body();$s=query('SELECT * FROM users WHERE username=? OR email=?',[$b['username']??'',$b['username']??'']);$x=$s->fetch();if(!$x||$x['status']!=='active'||!password_verify($b['password']??'',$x['password_hash']))fail('Invalid credentials',401);session_regenerate_id(true);$_SESSION['uid']=$x['id'];$_SESSION['csrf']=bin2hex(random_bytes(24));out(['user'=>user(),'csrf'=>$_SESSION['csrf']]);}
$u=user();
if($method!=='GET'&&!hash_equals($_SESSION['csrf']??'',$_SERVER['HTTP_X_CSRF_TOKEN']??''))fail('Invalid CSRF token',403);
if($path==='api/auth/me')out(['user'=>$u,'csrf'=>$_SESSION['csrf']??'']);
if($path==='api/auth/logout'&&$method==='POST'){session_destroy();out(['ok'=>true]);}
if($path==='api/users'&&$method==='GET'){roles($u,'admin','teacher');$sql="SELECT id,full_name,username,email,role,status,department,student_number,course,year_level,section FROM users WHERE role IN ('teacher','student')";if($u['role']==='teacher')$sql.=" AND role='student'";out(query($sql.' ORDER BY id DESC')->fetchAll());}
if($path==='api/users'&&$method==='POST'){roles($u,'admin');$b=body();foreach(['full_name','username','email','password','role'] as $k)if(empty($b[$k]))fail('Missing '.$k);if(!in_array($b['role'],['teacher','student']))fail('Invalid role');if(strlen($b['password'])<8)fail('Password must be at least 8 characters');query('INSERT INTO users(full_name,username,email,password_hash,role,department,student_number,course,year_level,section) VALUES(?,?,?,?,?,?,?,?,?,?)',[$b['full_name'],$b['username'],$b['email'],password_hash($b['password'],PASSWORD_DEFAULT),$b['role'],$b['department']??null,$b['student_number']??null,$b['course']??null,$b['year_level']??null,$b['section']??null]);logaction($u,'Created '.$b['role'].' account');out(['ok'=>true],201);}
if(preg_match('~^api/users/(\d+)$~',$path,$m)&&$method==='PATCH'){roles($u,'admin');$b=body();if(!in_array($b['status']??'', ['active','inactive']))fail('Invalid status');query("UPDATE users SET status=? WHERE id=? AND role<>'admin'",[$b['status'],$m[1]]);out(['ok'=>true]);}
if($path==='api/projects'&&$method==='GET'){$sql='SELECT p.*,t.full_name teacher_name,l.full_name leader_name,(SELECT COUNT(*) FROM project_members pm WHERE pm.project_id=p.id) member_count FROM projects p JOIN users t ON t.id=p.teacher_id LEFT JOIN users l ON l.id=p.leader_id';$args=[];if($u['role']==='teacher'){$sql.=' WHERE p.teacher_id=?';$args[]=$u['id'];}if($u['role']==='student'){$sql.=' WHERE EXISTS(SELECT 1 FROM project_members m WHERE m.project_id=p.id AND m.student_id=?)';$args[]=$u['id'];}out(query($sql.' ORDER BY p.updated_at DESC',$args)->fetchAll());}
if($path==='api/projects'&&$method==='POST'){roles($u,'admin','teacher');$b=body();if(empty($b['project_title']))fail('Project title required');$tid=$u['role']==='teacher'?$u['id']:($b['teacher_id']??0);if(!query("SELECT 1 FROM users WHERE id=? AND role='teacher' AND status='active'",[$tid])->fetch())fail('Select a valid teacher');query('INSERT INTO projects(project_title,description,teacher_id,deadline) VALUES(?,?,?,?)',[$b['project_title'],$b['description']??'',$tid,$b['deadline']?:null]);$id=db()->lastInsertId();logaction($u,'Created project #'.$id);out(['id'=>$id],201);}
if(preg_match('~^api/projects/(\d+)$~',$path,$m)){$id=(int)$m[1];$p=accessible($u,$id);if($method==='GET'){$members=query('SELECT u.id,u.full_name,u.student_number,m.member_role FROM project_members m JOIN users u ON u.id=m.student_id WHERE m.project_id=? ORDER BY m.member_role DESC,u.full_name',[$id])->fetchAll();$feedback=query('SELECT f.*,u.full_name teacher_name FROM feedback f JOIN users u ON u.id=f.teacher_id WHERE f.project_id=? ORDER BY f.id DESC',[$id])->fetchAll();$submissions=query('SELECT s.*,u.full_name uploader FROM submissions s JOIN users u ON u.id=s.submitted_by WHERE s.project_id=? ORDER BY s.id DESC',[$id])->fetchAll();$history=query('SELECT h.*,u.full_name actor FROM status_history h JOIN users u ON u.id=h.changed_by WHERE h.project_id=? ORDER BY h.id DESC',[$id])->fetchAll();out(compact('p','members','feedback','submissions','history'));}}
if(preg_match('~^api/projects/(\d+)/status$~',$path,$m)&&$method==='PATCH'){roles($u,'admin','teacher');$id=(int)$m[1];$p=accessible($u,$id);$b=body();$statuses=['Pending','In Progress','Under Review','For Revision','Approved','Completed'];if(!in_array($b['status']??'',$statuses,true))fail('Invalid status');$progress=filter_var($b['progress_percentage']??$p['progress_percentage'],FILTER_VALIDATE_INT);if($progress===false||$progress<0||$progress>100)fail('Invalid progress');db()->beginTransaction();query('UPDATE projects SET status=?,progress_percentage=? WHERE id=?',[$b['status'],$progress,$id]);query('INSERT INTO status_history(project_id,old_status,new_status,changed_by) VALUES(?,?,?,?)',[$id,$p['status'],$b['status'],$u['id']]);query('INSERT INTO notifications(user_id,title,message) SELECT student_id,?,? FROM project_members WHERE project_id=?',['Project status updated',$p['project_title'].' is now '.$b['status'],$id]);db()->commit();logaction($u,'Updated project #'.$id.' to '.$b['status']);out(['ok'=>true]);}
if(preg_match('~^api/projects/(\d+)/members$~',$path,$m)&&$method==='POST'){roles($u,'admin','teacher');$id=(int)$m[1];accessible($u,$id);$b=body();$sid=(int)($b['student_id']??0);if(!query("SELECT 1 FROM users WHERE id=? AND role='student' AND status='active'",[$sid])->fetch())fail('Invalid student');db()->beginTransaction();query('SELECT id FROM projects WHERE id=? FOR UPDATE',[$id]);$count=(int)query('SELECT COUNT(*) FROM project_members WHERE project_id=?',[$id])->fetchColumn();$leader=$count===0;query('INSERT INTO project_members(project_id,student_id,member_role) VALUES(?,?,?)',[$id,$sid,$leader?'leader':'member']);if($leader)query('UPDATE projects SET leader_id=? WHERE id=?',[$sid,$id]);db()->commit();out(['ok'=>true],201);}
if(preg_match('~^api/projects/(\d+)/feedback$~',$path,$m)&&$method==='POST'){roles($u,'admin','teacher');$id=(int)$m[1];$p=accessible($u,$id);$b=body();if(!trim($b['message']??''))fail('Feedback required');query('INSERT INTO feedback(project_id,teacher_id,message) VALUES(?,?,?)',[$id,$u['id'],$b['message']]);query('INSERT INTO notifications(user_id,title,message) SELECT student_id,?,? FROM project_members WHERE project_id=?',['New teacher feedback',$p['project_title'],$id]);out(['ok'=>true],201);}
if(preg_match('~^api/projects/(\d+)/submissions$~',$path,$m)&&$method==='POST'){$id=(int)$m[1];accessible($u,$id);if($u['role']!=='student')fail('Only students can submit',403);if(empty($_FILES['file'])||$_FILES['file']['error']!==UPLOAD_ERR_OK)fail('Upload failed');$f=$_FILES['file'];if($f['size']>10*1024*1024)fail('Maximum 10 MB');$ext=strtolower(pathinfo($f['name'],PATHINFO_EXTENSION));if(!in_array($ext,['pdf','doc','docx','ppt','pptx','zip']))fail('Unsupported file type');$dir=__DIR__.'/../monitoring_private_uploads';if(!is_dir($dir))mkdir($dir,0700,true);$name=bin2hex(random_bytes(16)).'.'.$ext;if(!move_uploaded_file($f['tmp_name'],$dir.'/'.$name))fail('Unable to store file',500);query('INSERT INTO submissions(project_id,submitted_by,file_name,file_path) VALUES(?,?,?,?)',[$id,$u['id'],basename($f['name']),$name]);out(['ok'=>true],201);}
if(preg_match('~^api/submissions/(\d+)/download$~',$path,$m)&&$method==='GET'){$s=query('SELECT * FROM submissions WHERE id=?',[$m[1]])->fetch();if(!$s)fail('File not found',404);accessible($u,$s['project_id']);$f=__DIR__.'/../monitoring_private_uploads/'.$s['file_path'];if(!is_file($f))fail('File missing',404);header_remove('Content-Type');header('Content-Type: application/octet-stream');header('Content-Disposition: attachment; filename="'.str_replace('"','',basename($s['file_name'])).'"');readfile($f);exit;}
if($path==='api/notifications'&&$method==='GET')out(query('SELECT * FROM notifications WHERE user_id=? ORDER BY id DESC LIMIT 50',[$u['id']])->fetchAll());
if(preg_match('~^api/notifications/(\d+)/read$~',$path,$m)&&$method==='PATCH'){query('UPDATE notifications SET is_read=1 WHERE id=? AND user_id=?',[$m[1],$u['id']]);out(['ok'=>true]);}
if($path==='api/activity'&&$method==='GET'){roles($u,'admin');out(query('SELECT a.*,u.full_name FROM activity_logs a LEFT JOIN users u ON a.user_id=u.id ORDER BY a.id DESC LIMIT 50')->fetchAll());}
fail('Endpoint not found',404);
}catch(PDOException $e){if(db()->inTransaction())db()->rollBack();error_log($e->getMessage());fail($e->getCode()==='23000'?'Duplicate or invalid record':'Database error',400);}catch(Throwable $e){error_log($e->getMessage());fail('Server error',500);}
